<?php
$title = 'Bulk installations';
$inventory = $inventory ?? ['trackers' => [], 'fls' => [], 'cameras' => [], 'sims' => []];
$clients = $clients ?? [];
$users = $users ?? [];
$supportUsers = $supportUsers ?? [];
$packageTypes = $packageTypes ?? \GPSDevice::packageTypes();
$rows = $rows ?? [['package_type' => 'Basic', 'installed_at' => date('Y-m-d')]];
$esc = static fn($value) => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$options = static function (array $products, string $selected = '', bool $optional = false) use ($esc): string {
    $html = $optional ? '<option value="">None</option>' : '<option value="">Choose item</option>';
    foreach ($products as $product) {
        $id = (string)($product['id'] ?? '');
        $identifier = trim((string)($product['imei'] ?? ''));
        $label = ($product['item_type'] ?? $product['device_type'] ?? 'Item') . ($identifier !== '' ? ' · ' . $identifier : '') . ' · stock ' . (int)($product['opening_stock'] ?? 0);
        $html .= '<option value="' . $esc($id) . '" data-identifier="' . $esc($identifier) . '"' . ($selected === $id ? ' selected' : '') . '>' . $esc($label) . '</option>';
    }
    return $html;
};
$clientOptions = static function (array $clients, string $selected = '') use ($esc): string {
    $html = '<option value="">Choose client</option>';
    foreach ($clients as $client) $html .= '<option value="' . (int)$client['id'] . '"' . ($selected === (string)$client['id'] ? ' selected' : '') . '>' . $esc($client['company_name']) . '</option>';
    return $html;
};
$userOptions = static function (array $users, string $selected = '', string $placeholder = 'Choose staff member') use ($esc): string {
    $html = '<option value="">' . $esc($placeholder) . '</option>';
    foreach ($users as $user) $html .= '<option value="' . (int)$user['id'] . '"' . ($selected === (string)$user['id'] ? ' selected' : '') . '>' . $esc($user['name']) . '</option>';
    return $html;
};
?>
<style>
.install-bulk-hero{padding:22px 25px;margin-bottom:18px;border-radius:16px;background:linear-gradient(115deg,#17243d,#334d7a);color:#fff}.install-bulk-hero h1{margin:0 0 5px;font-size:23px;font-weight:800}.install-bulk-hero p{margin:0;color:#c3cee0;font-size:12px}.install-row{position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;padding:15px 50px 15px 15px;border:1px solid #e7ebf1;border-radius:13px;background:#fff}.install-row+.install-row{margin-top:12px}.install-row label{font-size:10px;font-weight:700;color:#6e7c90;margin-bottom:5px}.install-row .form-control,.install-row .form-select{font-size:12px}.install-row .package-field{grid-column:span 2}.install-row .install-remove{position:absolute;right:12px;top:14px}.install-row .span-two{grid-column:span 2}@media(max-width:850px){.install-row{grid-template-columns:repeat(2,minmax(0,1fr))}.install-row .package-field{grid-column:span 2}}@media(max-width:520px){.install-row{grid-template-columns:1fr;padding-right:45px}.install-row .package-field,.install-row .span-two{grid-column:auto}}
</style>
<div class="install-bulk-hero"><h1>Bulk installations</h1><p>Add several installations in one go. Enter a unique tracker IMEI / serial for each installation; selected equipment is deducted from stock.</p></div>
<div class="card border-0 shadow-sm"><div class="card-body p-3 p-lg-4">
<?php if (!empty($error)): ?><div class="alert alert-danger" role="alert"><?= $esc($error) ?></div><?php endif; ?>
<?php if (!$inventory['trackers']): ?><div class="alert alert-warning">There are no trackers in stock. Tracker packages cannot be installed, but Camera only packages can still be recorded.</div><?php endif; ?>
<?php if (!$inventory['sims']): ?><div class="alert alert-warning" role="status">No registered SIM lines are available. Add SIM lines in Inventory to assign them to devices or cameras.</div><?php endif; ?>
<?php if (!$clients): ?><div class="alert alert-warning" role="status">No active clients are available. Add a client before recording an installation.</div><?php endif; ?>
<?php if (!$supportUsers): ?><div class="alert alert-warning" role="status">No active IT Support users are available. Add or activate an IT Support user before recording installations.</div><?php endif; ?>
<form method="post" id="install-bulk-form"><?= $this->csrfField() ?><div id="install-rows">
<?php foreach ($rows as $index => $row): $package = $row['package_type'] ?? 'Basic'; $cameraOnly = $package === 'Camera only'; $needsFls = in_array($package, ['Basic + FLS', 'Basic + FLS + Camera'], true); $needsCamera = in_array($package, ['Basic + FLS + Camera', 'Camera only', 'Camera + Basic'], true); ?>
<div class="install-row">
    <div class="package-field"><label>Package</label><select class="form-select install-package" name="installations[<?= (int)$index ?>][package_type]" required><?php foreach ($packageTypes as $type): ?><option value="<?= $esc($type) ?>" <?= $package === $type ? 'selected' : '' ?>><?= $esc($type) ?></option><?php endforeach; ?></select></div>
    <div class="<?= $cameraOnly ? 'd-none' : '' ?>"><label>Tracker from inventory</label><select class="form-select install-tracker" name="installations[<?= (int)$index ?>][tracker_product_id]" <?= $cameraOnly ? 'disabled' : 'required' ?>><?= $options($inventory['trackers'], (string)($row['tracker_product_id'] ?? '')) ?></select><input class="form-control mt-2 install-tracker-identifier" name="installations[<?= (int)$index ?>][tracker_identifier]" value="<?= $esc($row['tracker_identifier'] ?? '') ?>" inputmode="numeric" pattern="[0-9]+" maxlength="100" placeholder="Enter tracker IMEI / serial" <?= $cameraOnly ? 'disabled' : 'required' ?>></div>
    <div class="install-fls-wrap <?= $needsFls ? '' : 'd-none' ?>"><label>FLS from inventory</label><select class="form-select install-fls" name="installations[<?= (int)$index ?>][fls_product_id]" <?= $needsFls ? 'required' : 'disabled' ?>><?= $options($inventory['fls'], (string)($row['fls_product_id'] ?? ''), true) ?></select></div>
    <div class="install-camera-wrap <?= $needsCamera ? '' : 'd-none' ?>"><label>Camera from inventory</label><select class="form-select install-camera" name="installations[<?= (int)$index ?>][camera_product_id]" <?= $needsCamera ? 'required' : 'disabled' ?>><?= $options($inventory['cameras'], (string)($row['camera_product_id'] ?? ''), true) ?></select></div>
    <div><label>Device SIM line</label><select class="form-select install-sim" name="installations[<?= (int)$index ?>][sim_product_id]"><?= $options($inventory['sims'], (string)($row['sim_product_id'] ?? ''), true) ?></select></div>
    <div><label>Camera SIM line</label><select class="form-select install-sim" name="installations[<?= (int)$index ?>][camera_sim_product_id]"><?= $options($inventory['sims'], (string)($row['camera_sim_product_id'] ?? ''), true) ?></select></div>
    <div class="install-fls-serial-wrap <?= $needsFls ? '' : 'd-none' ?>"><label>FLS serial from inventory</label><input class="form-control install-fls-identifier" value="" placeholder="Selected FLS serial" readonly></div>
    <div class="install-camera-serial-wrap <?= $needsCamera ? '' : 'd-none' ?>"><label>Camera serial from inventory</label><input class="form-control install-camera-identifier" value="" placeholder="Selected camera serial" readonly></div>
    <div><label>Client</label><select class="form-select" name="installations[<?= (int)$index ?>][client_id]" required><?= $clientOptions($clients, (string)($row['client_id'] ?? '')) ?></select></div>
    <div><label>Installer</label><select class="form-select" name="installations[<?= (int)$index ?>][installer_id]" required><?= $userOptions($users, (string)($row['installer_id'] ?? ''), 'Choose installer') ?></select></div>
    <div><label>IT support</label><select class="form-select" name="installations[<?= (int)$index ?>][support_id]" required><?= $userOptions($supportUsers, (string)($row['support_id'] ?? ''), 'Choose IT support') ?></select></div>
    <div><label>Vehicle registration</label><input class="form-control" name="installations[<?= (int)$index ?>][registration_number]" maxlength="100" value="<?= $esc($row['registration_number'] ?? '') ?>"></div>
    <div><label>Vehicle chassis</label><input class="form-control" name="installations[<?= (int)$index ?>][chassis_number]" maxlength="100" value="<?= $esc($row['chassis_number'] ?? '') ?>"></div>
    <div><label>Installation date</label><input class="form-control" type="date" name="installations[<?= (int)$index ?>][installed_at]" value="<?= $esc(isset($row['installed_at']) ? substr((string)$row['installed_at'], 0, 10) : date('Y-m-d')) ?>"></div>
    <button class="btn btn-sm btn-outline-danger install-remove" type="button" aria-label="Remove installation row"><i class="fa-solid fa-trash"></i></button>
</div>
<?php endforeach; ?></div>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mt-3"><button class="btn btn-outline-primary" type="button" id="add-install-row"><i class="fa-solid fa-plus me-2"></i>Add another installation</button><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="/index.php?controller=gps">Cancel</a><button class="btn btn-primary" type="submit" <?= !$inventory['trackers'] && !$inventory['cameras'] ? 'disabled' : '' ?>><i class="fa-solid fa-layer-group me-2"></i>Save installations</button></div></div>
</form></div></div>
<script>
const installRows=document.getElementById('install-rows'),installOptions=<?= json_encode(['trackers'=>$inventory['trackers'],'fls'=>$inventory['fls'],'cameras'=>$inventory['cameras'],'sims'=>$inventory['sims'],'clients'=>$clients,'users'=>$users,'supportUsers'=>$supportUsers,'packages'=>$packageTypes], JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
function escapeInstallHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));}
function updateInventoryIdentifiers(row,resetTracker=false){const tracker=row.querySelector('.install-tracker'),trackerIdentifier=row.querySelector('.install-tracker-identifier'),inventoryIdentifier=tracker.selectedOptions[0]?.dataset.identifier||'',fls=row.querySelector('.install-fls'),camera=row.querySelector('.install-camera');trackerIdentifier.readOnly=inventoryIdentifier!=='';if(inventoryIdentifier)trackerIdentifier.value=inventoryIdentifier;else if(resetTracker)trackerIdentifier.value='';row.querySelector('.install-fls-identifier').value=fls.selectedOptions[0]?.dataset.identifier||'';row.querySelector('.install-camera-identifier').value=camera.selectedOptions[0]?.dataset.identifier||'';}
function syncInstallPackage(row){const pkg=row.querySelector('.install-package').value,cameraOnly=pkg==='Camera only',tracker=row.querySelector('.install-tracker'),trackerIdentifier=row.querySelector('.install-tracker-identifier'),fls=row.querySelector('.install-fls'),camera=row.querySelector('.install-camera'),needsFls=['Basic + FLS','Basic + FLS + Camera'].includes(pkg),needsCamera=['Basic + FLS + Camera','Camera only','Camera + Basic'].includes(pkg);tracker.parentElement.classList.toggle('d-none',cameraOnly);tracker.disabled=cameraOnly;tracker.required=!cameraOnly;trackerIdentifier.disabled=cameraOnly;trackerIdentifier.required=!cameraOnly;if(cameraOnly){tracker.value='';trackerIdentifier.value='';}fls.disabled=!needsFls;fls.required=needsFls;camera.disabled=!needsCamera;camera.required=needsCamera;row.querySelector('.install-fls-wrap').classList.toggle('d-none',!needsFls);row.querySelector('.install-camera-wrap').classList.toggle('d-none',!needsCamera);row.querySelector('.install-fls-serial-wrap').classList.toggle('d-none',!needsFls);row.querySelector('.install-camera-serial-wrap').classList.toggle('d-none',!needsCamera);if(!needsFls)fls.value='';if(!needsCamera)camera.value='';updateInventoryIdentifiers(row);syncInstallSimLines(row);}
function optionMarkup(products,optional){return (optional?'<option value="">None</option>':'<option value="">Choose item</option>')+products.map(p=>`<option value="${escapeInstallHtml(p.id)}" data-identifier="${escapeInstallHtml(p.imei||'')}">${escapeInstallHtml(p.item_type||p.device_type||'Item')}${p.imei?' · '+escapeInstallHtml(p.imei):''} · stock ${escapeInstallHtml(p.opening_stock||0)}</option>`).join('');}
function staffOptionMarkup(items,placeholder){return `<option value="">${escapeInstallHtml(placeholder)}</option>`+items.map(item=>`<option value="${escapeInstallHtml(item.id)}">${escapeInstallHtml(item.name)}</option>`).join('');}
function addInstallRow(){if(installRows.children.length>=50)return;const i=Date.now()+Math.floor(Math.random()*1000),row=document.createElement('div');row.className='install-row';row.innerHTML=`<div class="package-field"><label>Package</label><select class="form-select install-package" name="installations[${i}][package_type]" required>${installOptions.packages.map(p=>`<option value="${escapeInstallHtml(p)}">${escapeInstallHtml(p)}</option>`).join('')}</select></div><div><label>Tracker from inventory</label><select class="form-select install-tracker" name="installations[${i}][tracker_product_id]" required>${optionMarkup(installOptions.trackers,false)}</select><input class="form-control mt-2 install-tracker-identifier" name="installations[${i}][tracker_identifier]" placeholder="Enter tracker IMEI / serial" inputmode="numeric" pattern="[0-9]+" maxlength="100" required></div><div class="install-fls-wrap d-none"><label>FLS from inventory</label><select class="form-select install-fls" name="installations[${i}][fls_product_id]" disabled>${optionMarkup(installOptions.fls,true)}</select></div><div class="install-camera-wrap d-none"><label>Camera from inventory</label><select class="form-select install-camera" name="installations[${i}][camera_product_id]" disabled>${optionMarkup(installOptions.cameras,true)}</select></div><div><label>Device SIM line</label><select class="form-select install-sim" name="installations[${i}][sim_product_id]">${optionMarkup(installOptions.sims,true)}</select></div><div><label>Camera SIM line</label><select class="form-select install-sim" name="installations[${i}][camera_sim_product_id]">${optionMarkup(installOptions.sims,true)}</select></div><div class="install-fls-serial-wrap d-none"><label>FLS serial from inventory</label><input class="form-control install-fls-identifier" placeholder="Selected FLS serial" readonly></div><div class="install-camera-serial-wrap d-none"><label>Camera serial from inventory</label><input class="form-control install-camera-identifier" placeholder="Selected camera serial" readonly></div><div><label>Client</label><select class="form-select" name="installations[${i}][client_id]" required>${staffOptionMarkup(installOptions.clients.map(client=>({id:client.id,name:client.company_name})),'Choose client')}</select></div><div><label>Installer</label><select class="form-select" name="installations[${i}][installer_id]" required>${staffOptionMarkup(installOptions.users,'Choose installer')}</select></div><div><label>IT support</label><select class="form-select" name="installations[${i}][support_id]" required>${staffOptionMarkup(installOptions.supportUsers,'Choose IT support')}</select></div><div><label>Vehicle registration</label><input class="form-control" name="installations[${i}][registration_number]" maxlength="100"></div><div><label>Vehicle chassis</label><input class="form-control" name="installations[${i}][chassis_number]" maxlength="100"></div><div><label>Installation date</label><input class="form-control" type="date" name="installations[${i}][installed_at]" value="${new Date().toISOString().slice(0,10)}"></div><button class="btn btn-sm btn-outline-danger install-remove" type="button" aria-label="Remove installation row"><i class="fa-solid fa-trash"></i></button>`;installRows.append(row);syncInstallPackage(row);}
function syncInstallSimLines(row){const selects=[...row.querySelectorAll('.install-sim')],deviceSim=selects[0].value;[...selects[1].options].forEach(option=>{option.disabled=option.value!==''&&option.value===deviceSim;});if(selects[1].value===deviceSim)selects[1].value='';}
document.getElementById('add-install-row').addEventListener('click',addInstallRow);installRows.addEventListener('change',e=>{const row=e.target.closest('.install-row');if(e.target.matches('.install-package'))syncInstallPackage(row);else if(e.target.matches('.install-tracker'))updateInventoryIdentifiers(row,true);else if(e.target.matches('.install-fls,.install-camera'))updateInventoryIdentifiers(row);else if(e.target.matches('.install-sim'))syncInstallSimLines(row);});installRows.addEventListener('click',e=>{const button=e.target.closest('.install-remove');if(button&&installRows.children.length>1)button.closest('.install-row').remove();});installRows.querySelectorAll('.install-row').forEach(syncInstallPackage);
</script>
